1	import 'dart:async';
2	
3	import 'package:flutter_bloc/flutter_bloc.dart';
4	import 'package:fpdart/fpdart.dart';
5	
6	import '../../../../core/failure/failure.dart';
7	import '../../domain/entities/chat_message.dart';
8	import '../../domain/entities/chat_session.dart';
9	import '../../domain/entities/chat_stream_event.dart';
10	import '../../domain/repositories/chat_repository.dart';
11	import 'chat_state.dart';
12	
13	/// Drives `ChatScreen` — a DI `lazySingleton` (Code Map, mirroring
14	/// `MeusRegistrosCubit`): long-lived, so returning to Home/Chat within the
15	/// same app session never re-bootstraps the session/history it already
16	/// loaded (`init()`'s own no-op guard below).
17	class ChatCubit extends Cubit<ChatState> {
18	  ChatCubit(this._repository) : super(const ChatBootstrapLoading());
19	
20	  final ChatRepository _repository;
21	
22	  StreamSubscription<Either<Failure, ChatStreamEvent>>? _sendSubscription;
23	
24	  /// The in-flight [sendMessage]'s own completer, if any — [close] must
25	  /// complete it itself, since cancelling [_sendSubscription] never fires
26	  /// `onDone`/`onError` (review fix: `cancel()` alone left `sendMessage()`'s
27	  /// returned `Future` permanently unresolved when the cubit closed mid-send).
28	  Completer<void>? _sendCompleter;
29	
30	  /// Monotonic counter behind every locally generated [ChatUiMessage.id]
31	  /// (Code Map) — never the server's own message id (see `ChatStreamEvent`'s
32	  /// own doc on why `message_created`'s id goes unused here).
33	  int _localIdCounter = 0;
34	
35	  /// Whether a send is actively in flight right now — tracked locally
36	  /// rather than by scanning [ChatState.messages] for a persisted
37	  /// `streaming` status, since a message loaded from history/cache can
38	  /// legitimately carry that same status (e.g. one left over from an
39	  /// earlier dropped response, the I/O matrix's own scenario) without a
40	  /// send actually being in progress; scanning for it would permanently
41	  /// disable the composer in that case.
42	  bool _isSending = false;
43	
44	  /// An in-flight bootstrap, if any — reused by a concurrent `init()` call
45	  /// instead of starting a second bootstrap, so two near-simultaneous
46	  /// callers (e.g. two mounts before the first resolves) never both
47	  /// observe "no sessions" and both call `createSession()` (Boundaries:
48	  /// "silently ensure *one* Chat Session exists").
49	  Future<void>? _initFuture;
50	
51	  /// Boundaries: "Scroll-offset restore is in-memory only, keyed by
52	  /// `sessionId`, on `ChatCubit` (never Hive) — survives session switches
53	  /// within one app run, resets on restart." Lives on this long-lived
54	  /// `lazySingleton` cubit itself (Design Notes), never on [ChatReady] —
55	  /// a state value would otherwise have to be threaded through every
56	  /// unrelated `copyWith` call just to avoid losing it.
57	  final Map<String, double> _scrollOffsets = {};
58	
59	  /// Boundaries: "On opening Home/Chat, silently ensure one Chat Session
60	  /// exists (reuse the most recent from `chat-sessions-list`, else
61	  /// `chat-sessions-create` with no title)". A no-op once already
62	  /// [ChatReady] — `ChatScreen.initState()` calls this unconditionally on
63	  /// every mount, but a `lazySingleton` cubit may already be bootstrapped
64	  /// from an earlier visit.
65	  Future<void> init() {
66	    if (state is ChatReady || isClosed) {
67	      return Future.value();
68	    }
69	    return _initFuture ??= _bootstrap().whenComplete(() => _initFuture = null);
70	  }
71	
72	  Future<void> _bootstrap() async {
73	    emit(const ChatBootstrapLoading());
74	
75	    final sessionsResult = await _repository.listSessions();
76	    if (isClosed) {
77	      return;
78	    }
79	    // Captured by the closures below so the resulting [ChatReady] can
80	    // carry every known session (Code Map: "capture resolved sessions
81	    // into the emitted ChatReady"), not just the one picked to reuse.
82	    List<ChatSession> sessions = const [];
83	    final Either<Failure, ChatSession> sessionResult = await sessionsResult
84	        .match((failure) async => left(failure), (fetchedSessions) async {
85	          if (fetchedSessions.isEmpty) {
86	            final createResult = await _repository.createSession();
87	            return createResult.match((failure) => left(failure), (session) {
88	              sessions = [session];
89	              return right(session);
90	            });
91	          }
92	          sessions = fetchedSessions;
93	          // "reuse the most recent" — defensively re-sorts rather than
94	          // trusting `listSessions()`'s own ordering (its offline-cache
95	          // fallback already sorts `updatedAt` desc, but the live
96	          // server response's own ordering isn't documented either
97	          // way). `tryParse` (never `parse`) — same crash-safe pattern as
98	          // `AppDrawer`'s own session sort (review finding "Crash risk in
99	          // the new `_ConversasSection` sort"): a malformed `updatedAt`
100	          // must never crash bootstrap itself, so it falls back to the
101	          // epoch and simply sorts last instead of throwing.
102	          final mostRecent = [...fetchedSessions]..sort(
103	            (a, b) => (DateTime.tryParse(b.updatedAt) ?? DateTime(0))
104	                .compareTo(DateTime.tryParse(a.updatedAt) ?? DateTime(0)),
105	          );
106	          return right(mostRecent.first);
107	        });
108	    if (isClosed) {
109	      return;
110	    }
111	
112	    await sessionResult.match(
113	      (failure) async {
114	        if (!isClosed) {
115	          emit(ChatBootstrapError(failure));
116	        }
117	      },
118	      (session) async {
119	        final messagesResult = await _repository.listMessages(session.id);
120	        if (isClosed) {
121	          return;
122	        }
123	        messagesResult.match(
124	          (failure) => emit(ChatBootstrapError(failure)),
125	          (messages) => emit(
126	            ChatReady(
127	              sessionId: session.id,
128	              messages: messages.map(_fromDomain).toList(),
129	              sessions: sessions,
130	            ),
131	          ),
132	        );
133	      },
134	    );
135	  }
136	
137	  /// Boundaries: "Scroll-offset restore is in-memory only, keyed by
138	  /// `sessionId`" — `ChatScreen`'s own `ScrollController` listener calls
139	  /// this on every scroll update, so whichever offset a session was last
140	  /// left at is always the one [switchSession] hands back when that
141	  /// session becomes active again.
142	  void recordScrollOffset(String sessionId, double offset) {
143	    _scrollOffsets[sessionId] = offset;
144	  }
145	
146	  /// I/O matrix: "Switch session"/"Switch to already-active session" —
147	  /// a no-op [Right] when [sessionId] is already [ChatReady.sessionId]
148	  /// (the drawer still closes, nothing reloads/re-fetches); otherwise
149	  /// fetches that session's own history via `listMessages` (reused as-is,
150	  /// Code Map) and makes it active, handing [ChatReady.restoreScrollOffset]
151	  /// whatever [recordScrollOffset] last captured for it (`null` if this
152	  /// session was never scrolled in this app run — `ChatScreen`'s own cue
153	  /// to jump to the bottom instead). A no-op while bootstrap hasn't
154	  /// resolved yet, same guard shape as [sendMessage].
155	  Future<Either<Failure, Unit>> switchSession(String sessionId) async {
156	    final current = state;
157	    if (current is! ChatReady) {
158	      return right(unit);
159	    }
160	    if (sessionId == current.sessionId) {
161	      return right(unit);
162	    }
163	    // Review finding: "Cross-session stream leakage" — an AI response
164	    // still streaming into the *old* session must never be left running
165	    // once we switch away from it; its orphaned subscription's
166	    // `onData`/`onDone` would otherwise go on to mutate whichever session
167	    // becomes active next.
168	    await _cancelInFlightSend();
169	    final messagesResult = await _repository.listMessages(sessionId);
170	    if (isClosed) {
171	      return right(unit);
172	    }
173	    return messagesResult.match((failure) => left(failure), (messages) {
174	      if (!isClosed) {
175	        emit(
176	          ChatReady(
177	            sessionId: sessionId,
178	            messages: messages.map(_fromDomain).toList(),
179	            sessions: current.sessions,
180	            restoreScrollOffset: _scrollOffsets[sessionId],
181	          ),
182	        );
183	      }
184	      return right(unit);
185	    });
186	  }
187	
188	  /// I/O matrix: "New session online"/"New session offline" — calls
189	  /// `createSession()` (reused as-is, Code Map; already blocked offline
190	  /// at the repository level, Boundaries). On any [Left] (including
191	  /// [Failure.networkOffline]), the current session is left completely
192	  /// untouched — no state is emitted at all, only the [Failure] is handed
193	  /// back for `AppDrawer` to surface as a transient `SnackBar`
194	  /// (Boundaries). On success, the new session opens empty and becomes
195	  /// active, prepended to [ChatReady.sessions].
196	  Future<Either<Failure, Unit>> startNewSession() async {
197	    final current = state;
198	    if (current is! ChatReady) {
199	      return right(unit);
200	    }
201	    // Review finding: "Cross-session stream leakage" — same rationale as
202	    // [switchSession]'s own cancellation above; a brand new session is
203	    // never the same session as [current], so this always needs to run
204	    // (unlike [switchSession], there's no same-session no-op branch to
205	    // skip it for).
206	    await _cancelInFlightSend();
207	    final result = await _repository.createSession();
208	    if (isClosed) {
209	      return right(unit);
210	    }
211	    return result.match((failure) => left(failure), (session) {
212	      if (!isClosed) {
213	        emit(
214	          ChatReady(
215	            sessionId: session.id,
216	            messages: const [],
217	            sessions: [session, ...current.sessions],
218	          ),
219	        );
220	      }
221	      return right(unit);
222	    });
223	  }
224	
225	  ChatUiMessage _fromDomain(ChatMessage message) => ChatUiMessage(
226	    id: message.id,
227	    role: message.role,
228	    content: message.content,
229	    status: message.status,
230	  );
231	
232	  /// Boundaries: optimistic user bubble, then subscribes to
233	  /// `ChatRepository.sendMessage`'s own stream, appending tokens as they
234	  /// arrive and finalizing/failing the AI bubble on `done`/any `Left` —
235	  /// the bubble's own [ChatUiMessage.content] is never cleared on failure
236	  /// (I/O matrix), only its [ChatUiMessage.status] changes.
237	  ///
238	  /// A no-op while [state] isn't [ChatReady] (bootstrap still in flight
239	  /// or failed — the composer is disabled in that case anyway), while
240	  /// [content] is blank once trimmed, or while [_isSending] is already
241	  /// true — this story never races two concurrent sends against the one
242	  /// in-memory session (Boundaries: no offline lock/composer-disable UI
243	  /// of its own exists yet, Story 6.3's job, so this guard is the one
244	  /// thing standing in for it here). Deliberately not keyed off any
245	  /// loaded message's persisted `streaming` status — a message restored
246	  /// from history/cache can legitimately carry that status without a
247	  /// send actually being in flight (I/O matrix: mid-stream drop).
248	  Future<void> sendMessage(String content) async {
249	    final trimmed = content.trim();
250	    if (trimmed.isEmpty) {
251	      return;
252	    }
253	    final current = state;
254	    if (current is! ChatReady) {
255	      return;
256	    }
257	    if (_isSending) {
258	      return;
259	    }
260	    _isSending = true;
261	
262	    final userMessage = ChatUiMessage(
263	      id: _nextLocalId(),
264	      role: ChatMessageRole.user,
265	      content: trimmed,
266	      status: ChatMessageStatus.complete,
267	    );
268	    final aiMessage = ChatUiMessage(
269	      id: _nextLocalId(),
270	      role: ChatMessageRole.assistant,
271	      content: '',
272	      status: ChatMessageStatus.streaming,
273	    );
274	    emit(
275	      current.copyWith(
276	        messages: [...current.messages, userMessage, aiMessage],
277	        isSending: true,
278	      ),
279	    );
280	
281	    await _sendSubscription?.cancel();
282	    final completer = Completer<void>();
283	    _sendCompleter = completer;
284	    _sendSubscription = _repository
285	        .sendMessage(current.sessionId, trimmed)
286	        .listen(
287	          (event) {
288	            event.match(
289	              (failure) => _markFailed(aiMessage.id),
290	              (streamEvent) => _applyStreamEvent(aiMessage.id, streamEvent),
291	            );
292	          },
293	          onError: (Object _, StackTrace _) {
294	            // RNF09: no exception escapes the cubit — a stream-level
295	            // error (shouldn't happen, `ChatRemoteDataSource.sendMessage`
296	            // never lets one through unmapped) still only fails the
297	            // bubble, never crashes.
298	            _markFailed(aiMessage.id);
299	            _finishSending();
300	            if (!completer.isCompleted) {
301	              completer.complete();
302	            }
303	            _sendCompleter = null;
304	          },
305	          onDone: () {
306	            _finishSending();
307	            if (!completer.isCompleted) {
308	              completer.complete();
309	            }
310	            _sendCompleter = null;
311	          },
312	          cancelOnError: false,
313	        );
314	    await completer.future;
315	  }
316	
317	  /// Clears both the internal re-entrancy guard and the UI-facing
318	  /// [ChatReady.isSending] signal once a send's stream has ended (`done`,
319	  /// an in-band error, or a stream-level error) — the single place both
320	  /// flip back together.
321	  void _finishSending() {
322	    _isSending = false;
323	    if (isClosed) {
324	      return;
325	    }
326	    final current = state;
327	    if (current is ChatReady) {
328	      emit(current.copyWith(isSending: false));
329	    }
330	  }
331	
332	  void _applyStreamEvent(String aiMessageId, ChatStreamEvent event) {
333	    if (isClosed) {
334	      return;
335	    }
336	    final current = state;
337	    if (current is! ChatReady) {
338	      return;
339	    }
340	    switch (event) {
341	      case ChatMessageCreatedEvent():
342	        // Design Notes: the persisted *user*-message id — no UI-facing
343	        // use yet in this story (Story 6.3's retry call is the first
344	        // consumer).
345	        break;
346	      case ChatTokenEvent(delta: final delta):
347	        emit(
348	          current.copyWith(
349	            messages: [
350	              for (final message in current.messages)
351	                if (message.id == aiMessageId)
352	                  message.copyWith(content: message.content + delta)
353	                else
354	                  message,
355	            ],
356	          ),
357	        );
358	      case ChatDoneEvent():
359	        emit(
360	          current.copyWith(
361	            messages: [
362	              for (final message in current.messages)
363	                if (message.id == aiMessageId)
364	                  message.copyWith(status: ChatMessageStatus.complete)
365	                else
366	                  message,
367	            ],
368	          ),
369	        );
370	    }
371	  }
372	
373	  /// I/O matrix: "Mid-stream drop"/"In-band `error` event" — marks the one
374	  /// bubble `failed`, by id, leaving its already-streamed-in text exactly
375	  /// as-is (never cleared, Boundaries).
376	  void _markFailed(String aiMessageId) {
377	    if (isClosed) {
378	      return;
379	    }
380	    final current = state;
381	    if (current is! ChatReady) {
382	      return;
383	    }
384	    emit(
385	      current.copyWith(
386	        messages: [
387	          for (final message in current.messages)
388	            if (message.id == aiMessageId)
389	              message.copyWith(status: ChatMessageStatus.failed)
390	            else
391	              message,
392	        ],
393	      ),
394	    );
395	  }
396	
397	  String _nextLocalId() => 'local-${_localIdCounter++}';
398	
399	  /// Review finding: "Cross-session stream leakage" — [switchSession]/
400	  /// [startNewSession] call this before touching anything else whenever
401	  /// they're about to make a *different* session active, so a response
402	  /// still streaming into the session being left behind can never go on
403	  /// to mutate the one that replaces it. Exactly [close]'s own cleanup
404	  /// below (cancel the subscription, resolve the stranded [sendMessage]
405	  /// caller, clear the re-entrancy guard), just without closing the cubit
406	  /// itself — a no-op when nothing is actually in flight.
407	  Future<void> _cancelInFlightSend() async {
408	    if (!_isSending) {
409	      return;
410	    }
411	    await _sendSubscription?.cancel();
412	    _sendSubscription = null;
413	    final completer = _sendCompleter;
414	    if (completer != null && !completer.isCompleted) {
415	      completer.complete();
416	    }
417	    _sendCompleter = null;
418	    _isSending = false;
419	  }
420	
421	  @override
422	  Future<void> close() {
423	    _sendSubscription?.cancel();
424	    final completer = _sendCompleter;
425	    if (completer != null && !completer.isCompleted) {
426	      completer.complete();
427	    }
428	    _sendCompleter = null;
429	    return super.close();
430	  }
431	}
