296	  final TextEditingController controller;
297	  final FocusNode focusNode;
298	  final VoidCallback onSend;
299	
300	  @override
301	  Widget build(BuildContext context) {
302	    return BlocBuilder<ChatCubit, ChatState>(
303	      builder: (context, state) {
304	        final canSend = state is ChatReady && !state.isSending;
305	        return SafeArea(
306	          top: false,
